create table public.reviews (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id) on delete cascade, product_id uuid not null references public.products(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, rating smallint not null check(rating between 1 and 5), title text, body text, status text not null default 'pending' check(status in ('pending','published','rejected')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(product_id,user_id));
